package com.thilaga.fruitmachine.domain;

import java.util.Optional;
import java.util.UUID;

/**
 * Port for machine storage (CLD-01). Implemented in infrastructure. The methods that change a
 * machine run inside the caller's transaction; {@link #findForUpdate} takes a row lock (UC-12).
 */
public interface MachineRepository {

  /** Stores a new machine with zero totals. Id is generated by the caller (D-c). */
  void insert(UUID id, Machine machine);

  /** Reads a machine without a lock (UC-06). */
  Optional<MachineState> find(UUID id);

  /**
   * Reads a machine under a row lock held until the transaction ends. Throws {@link
   * MachineBusyException} on lock timeout or deadlock.
   */
  Optional<Machine> findForUpdate(UUID id);

  /** Writes the machine's current float and free-play balance. */
  void save(UUID id, Machine machine);

  /** Adds one play to history and updates the play totals (BR-10, ERD play). */
  void recordPlay(UUID id, PlayResult result, boolean usedFreePlay);

  /** Adds one refill to history and updates the refill total (D11). */
  void recordRefill(UUID id, long amountPence, long floatAfterPence);
}
